// Preloaded by `bun test` (see bunfig.toml). Do NOT edit this file.
//
// If nothing is listening on BASE_URL, this starts your server (`bun run src/server.ts`)
// for the duration of the test run and stops it afterwards. If you already have `bun dev`
// running, the tests simply use it.
import { afterAll } from 'bun:test'
import { BASE } from './helpers'

async function isUp() {
  try {
    await fetch(BASE, { signal: AbortSignal.timeout(500) })
    return true // any HTTP answer (even a 404) means the server is there
  } catch {
    return false
  }
}

if (!(await isUp()) && !process.env.BASE_URL) {
  const port = new URL(BASE).port || '3000'
  const child = Bun.spawn(['bun', 'run', 'src/server.ts'], {
    env: { ...process.env, PORT: port },
    stdout: 'ignore',
    stderr: 'inherit',
  })
  // A top-level afterAll in a preload file runs once, after the last test file.
  afterAll(() => child.kill())
  process.on('exit', () => child.kill())

  const deadline = Date.now() + 10_000
  while (Date.now() < deadline && !(await isUp())) await Bun.sleep(100)

  if (await isUp()) console.log(`[setup] started src/server.ts on ${BASE} for this test run`)
  else console.error(`[setup] src/server.ts did not answer on ${BASE} within 10 s`)
}
